                    .isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
                throw new ClaimStatusRefusedException("A SETTLED claim can be voided only within "
                        + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
            }
        }
        if (claim.status() == ClaimStatus.PENDING && (next == ClaimStatus.SETTLED || next == ClaimStatus.OPEN)
                && !steward) {
            throw new ClaimStatusRefusedException("Only a steward can approve or reject a pending claim.");
        }
        if (claim.status() == ClaimStatus.PENDING && next == ClaimStatus.OPEN && reason.isEmpty()) {
            throw new ClaimStatusRefusedException("Give a reason to reject the claim.");
        }
        // While the sheet has void reasons, a claim is voided only with one of them; with none, no reason is kept.
        if (next == ClaimStatus.VOID) {
            List<String> reasons = voidReasons.list(claim.sheetId());
            if (reasons.isEmpty()) {
                voidReason = "";
            } else if (!reasons.contains(voidReason)) {
                throw new ClaimVoidReasonNeededException(voidReason.isEmpty()
                        ? "Choose a void reason to void the claim."
                        : "\"" + voidReason + "\" is not one of the sheet's void reasons.");
            }
        }
        // Settling (or approving) freezes the late charge on the sheet's today into the due.
        BigDecimal due = settings.withLate(claim, due(claim, people, rates, settings), sheets.today(claim.sheetId()));
        // A claim whose due is above the proof threshold in force on its date (its person's grade's, else the sheet's) is settled or approved only once it has a
        // proof, whoever settles it, and before the clerk limit is considered (a due of n/a is within any threshold).
        if (next == ClaimStatus.SETTLED && claim.proofs() == 0 && due != null) {
            BigDecimal threshold = settings.proofThreshold(claim);
            if (threshold != null && due.compareTo(threshold) > 0) {
                throw new ClaimProofNeededException("The claim's due is above the proof threshold (" + threshold.toPlainString()
                        + "): add a proof before it is " + (claim.status() == ClaimStatus.PENDING ? "approved." : "settled."));
            }
        }
        // A claim whose due is above the note threshold in force on its date is opened only once it has a note (a due
        // of n/a is within any threshold).
        if (next == ClaimStatus.OPEN && claim.status() == ClaimStatus.DRAFT && due != null
                && (claim.note() == null || claim.note().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(claim.sheetId(), claim.date());
            if (threshold != null && due.compareTo(threshold) > 0) {
                throw new ClaimNoteNeededException("The claim's due is above the note threshold (" + threshold.toPlainString()
                        + "): give it a note before it is opened.");
            }
        }
        // A clerk settles only a claim whose due is at or below the clerk limit (a due of n/a is within any
        // limit); above it the claim goes PENDING, for a steward to approve. A steward settles anything.
        if (next == ClaimStatus.SETTLED && claim.status() == ClaimStatus.OPEN && due != null && !steward) {
            BigDecimal limit = settings.clerkLimit(claim.sheetId());
            if (limit != null && due.compareTo(limit) > 0) {
                next = ClaimStatus.PENDING;
            }
        }
        // A DRAFT claim belonging to a period that caps its claims (its due-by falls in it) is opened only while its
        // person has fewer OPEN or PENDING claims in the period than the cap.
        if (next == ClaimStatus.OPEN && claim.status() == ClaimStatus.DRAFT) {
            Period capped = periods.on(claim.sheetId(), claim.dueBy());
            if (capped != null && capped.cap() != null
                    && claims.openInPeriod(claim.sheetId(), claim.personId(), capped) >= capped.cap()) {
                throw new ClaimStatusRefusedException("The person already has " + capped.cap()
                        + " open or pending claims in the period " + capped.name() + ", its cap.");
            }
        }
        // While the sheet numbers by period (its today on or after the from-date), an opened claim is numbered
        // within the period its due-by falls in, or in the no-period sequence; otherwise sheet-wide.
        String scope = null;
        LocalDate numberingFrom = settings.periodNumberingFrom(claim.sheetId());
        if (next == ClaimStatus.OPEN && numberingFrom != null && !sheets.today(claim.sheetId()).isBefore(numberingFrom)) {
            Period period = periods.on(claim.sheetId(), claim.dueBy());
            scope = period == null ? "" : period.name();
        }
        Claim changed = claims.changeStatus(claim, next, due, user, scope);
        if (changed == null) {
            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
        }
        // Settled one at a time, the claim leaves any batch that settled it before (a bulk settle records its batch after).
        if (!decision && (next == ClaimStatus.SETTLED || next == ClaimStatus.PENDING)) {
            batches.remove(changed.id());
        }
        if (next == ClaimStatus.VOID && !voidReason.isEmpty()) {
            voidReasons.voided(changed.id(), voidReason);
        }
        claims.log(changed, user, sheets.today(claim.sheetId()), rollup.figure(changed));
        responseOut.set(ClaimResponse.from(changed));
        requestOut.set(new ClaimStatusRequest(action, reason, voidReason));
    }

    /**
     * The claim's due now, before its late charge: the figure its person's last statement bound it to (a PENDING
     * claim is not bound: its figure is live), otherwise its amount times its
     * person's grade's rate on the claim's date, rounded by the policy date (not yet floored); null when none applies.
     */
    private static BigDecimal due(Claim claim, People people, Rates rates, Settings settings) {
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person == null) {
            return null;
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
        return settings.live(claim, rate);
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditClaimStatus {
    public void audit(@Val Claim loaded, @Val ClaimResponse changed, @Val ClaimStatusRequest request, People people,
            ServerHttpConnection connection, Audit audit) {
        Person person = people.find(loaded.sheetId(), loaded.personId());
        List<String> fields = new ArrayList<>(List.of("person=" + (person == null ? "" : person.name()),
                "amount=" + changed.amount(), "date=" + changed.date()));
        // A voided claim's line carries the number it had.
        String number = changed.number() != null ? changed.number() : loaded.number();
        if (number != null) {
            fields.add("number=" + number);
        }
        ClaimStatus status = ClaimStatus.valueOf(changed.status());
        // A settled (or approved) claim's line carries the due it was fixed at.
        if (status == ClaimStatus.SETTLED) {
            fields.add("due=" + (changed.settledDue() == null ? "n/a" : changed.settledDue()));
        }
        // A voided SETTLED claim's line carries the frozen figure it takes out of the totals.
        if (loaded.status() == ClaimStatus.SETTLED && status == ClaimStatus.VOID) {
            fields.add("reversed=" + (loaded.settledDue() == null ? "n/a" : loaded.settledDue().toPlainString()));
        }
        // A rejected claim's line carries the steward's reason.
        if (loaded.status() == ClaimStatus.PENDING && status == ClaimStatus.OPEN) {
            fields.add("reason=" + request.reason());
        }
        // A claim voided with a reason from the sheet's list carries it.
        if (status == ClaimStatus.VOID && request.voidReason() != null && !request.voidReason().isEmpty()) {
            fields.add("reason=" + request.voidReason());
        }
        audit.record(Audit.line(status.event(loaded.status()), loaded.sheetId(),
                Audit.user(connection), fields.toArray(String[]::new)));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim made by a person on a sheet. {@code amount} is 0.00 or more, in two decimals. {@code number}
 * is given when the claim is opened (null for a draft or a voided claim). {@code settledDue} is the due fixed
 * when it was settled (null when not settled, or settled while no rate of its grade applied on its date).
 * {@code openedBy} is the user who opened it (null when never opened). {@code stated} is whether its person's
 * last statement bound it, at {@code statedDue} (null when it had no figure then). A claim with a negative amount is a
 * correction: {@code corrects} is the number of the SETTLED claim of the same person it corrects (null for any other claim).
 * {@code dueBy} is fixed when the claim is made, the terms-th business day after its date (see {@code Holidays#dueBy}), and kept when its terms or its date change later; a holiday added later on or before it works it out again from its date with the terms it was fixed with (see {@code Claims#refixDueBys}).
 * {@code deferredUntil} is the date an OPEN claim was deferred to (null when never deferred).
 * {@code proofs} is how many proofs it has been given (0 for none).
 * {@code splitFrom} is the number of the claim it was split off (null for any other claim).
 * {@code lateEntry} is whether it was added while the period its due-by falls in was soft-closed.
 * {@code remindedOn} is the last sheet's today a reminder was written for it (null when never reminded).
 * {@code ref} is its external reference, unique on the sheet without regard to case (null when it has none).
 * {@code tags} are its tags, trimmed, lower-cased, without repeats and sorted (empty for none).
 */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, LocalDate remindedOn, String ref, java.util.List<String> tags) {

    public Claim with(ClaimInput input, LocalDate date) {
        return new Claim(id, sheetId, personId, input.amount(), date, input.note(), status, number, settledDue, openedBy, stated, statedDue, input.corrects(), dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, input.ref(), input.tags());
    }

    public Claim withStatus(ClaimStatus status, String number, BigDecimal settledDue, String openedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags);
    }

    /** The claim moved to another person: unbound from any statement, so live until their next one. */
    public Claim withPerson(long personId) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags);
    }

    /** The claim re-dated to {@code date}, numbered {@code number}. */
    public Claim withDate(LocalDate date, String number) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags);
    }

    /** The claim deferred to {@code until}. */
    public Claim withDeferredUntil(LocalDate until) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, until, proofs, splitFrom, lateEntry, remindedOn, ref, tags);
    }

    /** The claim with {@code amount} as its amount, unbound from any statement (live until its person's next one). */
    public Claim withAmountUnbound(BigDecimal amount) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags);
    }

    /** The claim with {@code proofs} proofs. */
    public Claim withProofs(int proofs) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags);
    }

    /** The claim reminded on {@code on}. */
    public Claim withRemindedOn(LocalDate on) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, on, ref, tags);
    }

    /**
     * Whether the claim is deferred on {@code today}: an OPEN claim deferred to a date the sheet's today has not reached
     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
     */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && (today == null || today.isBefore(deferredUntil));
    }

    /** A correction: its due is its amount times the rate, with no floor and no late charge. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }
}

