import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { patronSharesOf, patronsQuery } from '../patrons/patronsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useCap, useFloor, useLate } from '../settings/settingsQuery';
import { agedDue, excess, figure, personDue, personSum, ratesQuery, recentSettled, settledAndOpen, sumDue, sumOfShares, trimmedSum } from './ratesQuery';

function useSheetData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    floor: useFloor(sheetId),
    late: useLate(sheetId),
    cap: useCap(sheetId),
  };
}

function ClaimDue({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const { people, rates, floor, late } = useSheetData(sheetId);
  const person = people.find((p) => p.id === claim.personId);
  return <td data-testid="claim-due">{figure(claim, rates, person, floor, late)}</td>;
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late, cap } = useSheetData(sheetId);
  return <td data-testid="person-due-total">{personDue(people.find((p) => p.id === personId), people, claims, rates, today, floor, late, cap)}</td>;
}

/** What a person's figures add up to above the sheet's cap; 0.00 when they are not above it. */
function PersonExcess({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late, cap } = useSheetData(sheetId);
  return <td data-testid="person-excess">{excess(personSum(people.find((p) => p.id === personId), people, claims, rates, today, floor, late), cap)}</td>;
}
  const days = (Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${overdueFrom(claim, late)}T00:00:00Z`)) / 86_400_000;
  return BigInt(Math.floor(days / 30));
}

/** The date (yyyy-mm-dd) `days` after `date`. */
function addDays(date: string, days: number): string {
  return new Date(Date.parse(`${date}T00:00:00Z`) + days * 86_400_000).toISOString().slice(0, 10);
}

/**
 * A claim's figure: a settled claim's frozen due (its late charge frozen in), otherwise its rate figure — the one its
 * person's last statement bound it to (a PENDING claim is not bound: it shows its live figure), otherwise its amount times the rate, on the claim's date, of
 * the grade its person had on that date (rounded by the policy date, see `roundsHalfUp`). An overdue claim's late charge — for every full 30 days overdue, the late
 * percent in force on that boundary date (the due-by plus the grace plus 30, 60, 90 ... days) of that rate figure plus the charges of the boundaries before it (compounding), each rounded like the claim, added up — is added on top: a statement
 * never binds it, so it follows the sheet's today. Last, the sum is raised to the sheet's `floor` in force on the claim's date (two decimals).
 * A correction has neither floor nor late charge.
 */
export function figure(claim: Claim, rates: Rate[], person: Person | undefined, floor: DatedValue[], late: Late): string {
  if (claim.settledDue !== null) return claim.settledDue;
  const halfUp = roundsHalfUp(claim, late);
  const bound = claim.stated && claim.status !== 'PENDING'
    ? (claim.statedDue ?? 'n/a')
    : due(claim.amount, rateFor(rates, gradeOn(person, claim.date), claim.date), halfUp);
  if (isCorrection(claim) || bound === 'n/a') return bound;
  const months = lateMonths(claim, late);
  const from = overdueFrom(claim, late);
  let total = hundredths(bound);
  for (let n = 1n; n <= months; n++) {
    total += dueCents(show(total), valueOn(late.pct, addDays(from, Number(n) * 30)) ?? DEFAULT_LATE_PCT, halfUp);
  }
  return floored(show(total), valueOn(floor, claim.date) ?? DEFAULT_FLOOR);
}

function floored(live: string, floor: string): string {
  return live === 'n/a' || hundredths(live) >= hundredths(floor) ? live : show(hundredths(floor));
}

/**
 * A person's figures added up, before the cap: the sum of their counting claims' rounded figures, as each claim shows it. With no rate today and no figure it is n/a; otherwise it is the sum of the figures there are.
 */
export function personSum(person: Person | undefined, people: Person[], claims: Claim[], rates: Rate[], today: string, floor: DatedValue[], late: Late): string {
  if (!person) return 'n/a';
  const rate = rateFor(rates, gradeOn(person, today), today);
  const figures = claims
    .filter((c) => c.personId === person.id && counts(c, people, today))
    .map((c) => figure(c, rates, person, floor, late))
    .filter((d) => d !== 'n/a');
  return rate === undefined && figures.length === 0 ? 'n/a' : sumDue(figures);
}

/**

/**
 * An OPEN claim deferred to a date the sheet's `today` has not reached: it counts in no total, is not overdue and
 * cannot be settled. From that day on it is an OPEN claim like any other.
 */
export const isDeferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && (today === '' || today < c.deferredUntil);

/**
 * Only open (OPEN or PENDING) and SETTLED claims count toward claimed, due and every total; drafts, voided and
 * deleted ones do not, nor do a person's open claims dated within one of their holds, or once the sheet's `today` reaches
 * their retirement date, unless a statement bound them, nor an OPEN claim deferred on the sheet's `today`.
 */
export const counts = (c: Claim, people: Person[], today: string) =>
  !isDeferred(c, today) &&
  (c.status === 'SETTLED' ||
  (isOpen(c) &&
    ((c.stated && c.status !== 'PENDING') || !leftOut(people.find((p) => p.id === c.personId), c.date, today))));

/** Whether the person's unbound open claim dated `date` is left out: within a hold, or retired by `today`. */
const leftOut = (person: Person | undefined, date: string, today: string) =>
  heldOn(person, date) || (!!person?.retiredFrom && !!today && person.retiredFrom <= today);

/** The first day (yyyy-mm-dd) of the 30 days up to and including the sheet's `today`. */
const activeFrom = (today: string) => new Date(Date.parse(`${today}T00:00:00Z`) - 29 * 86_400_000).toISOString().slice(0, 10);

/**
 * Whether the person is active: they have an open (OPEN or PENDING) claim that counts, dated within the 30 days up to
 * and including the sheet's `today` (never while `today` is not loaded).
 */
export function isActive(personId: number, claims: Claim[], people: Person[], today: string): boolean {
  if (today === '') return false;
  const from = activeFrom(today);
  return claims.some(
    (c) => c.personId === personId && isOpen(c) && counts(c, people, today) && from <= c.date && c.date <= today,
  );
}

/** Under the sheet's key, so re-loading the sheet re-reads its claims. */
export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

